-- Environment variables live in ~/.config/uwsm/env (generated by
-- ../hyprland.nix), so that systemd user services get them as well. UWSM
-- sets XDG_CURRENT_DESKTOP, XDG_SESSION_DESKTOP and XDG_SESSION_TYPE itself.

hl.config({
  xwayland = {
    force_zero_scaling = true,
  },

  ecosystem = {
    no_update_news = true,
  },
})
